def solve_case(case):
    s = case['s']
    n = len(s)
    if n == 0:
        return 0
    lps = [0] * n
    length = 0
    i = 1
    while i < n:
        if s[i] == s[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1
    p = n - lps[-1]
    if n % p == 0:
        return p
    else:
        return n

