def solve_case(case):
    s = case["s"]
    ch = case["ch"]
    if not ch:
        return s
    first = s.find(ch)
    if first == -1:
        return s
    last = s.rfind(ch)
    if first == last:
        return s[:first] + s[first+len(ch):]
    return s[:first] + s[first+len(ch):last] + s[last+len(ch):]

