from math import comb

def solve_case(case):
    n = case['n']
    if n < 0:
        return 0
    bell = [1]
    for i in range(1, n + 1):
        nxt = 0
        for k in range(i):
            nxt += comb(i - 1, k) * bell[k]
        bell.append(nxt)
    return bell[n]

