def solve_case(case):
    s = str(case['n'])
    if s[0] == '-':
        return False
    if len(s) < 3:
        return False
    a = s[0]
    b = s[1]
    if a == b:
        return False
    for i, ch in enumerate(s):
        if i % 2 == 0:
            if ch != a:
                return False
        else:
            if ch != b:
                return False
    return True

