def solve_case(case):
    n = case['n']
    if n == 0:
        return 0
    n = abs(n)
    cnt = 1
    exp = 0
    while n % 2 == 0:
        exp += 1
        n //= 2
    if exp:
        cnt *= (exp + 1)
    f = 3
    while f * f <= n:
        exp = 0
        while n % f == 0:
            exp += 1
            n //= f
        if exp:
            cnt *= (exp + 1)
        f += 2
    if n > 1:
        cnt *= 2
