def solve_case(case):
    num = case['num']
    if num < 0:
        return 0
    s = str(num)
    if all(ch == '9' for ch in s):
        return int('1' + '0'*(len(s)-1) + '1')
    n = len(s)
    half = (n + 1) // 2
    left = s[:half]
    def make_pal(left_str, length):
        if length % 2 == 0:
            return left_str + left_str[::-1]
        else:
            return left_str + left_str[-2::-1]
    cand = make_pal(left, n)
    if int(cand) > num:
        return int(cand)
    else:
        new_left = str(int(left) + 1)
        return int(make_pal(new_left, n))

