def solve_case(case):
    n = case['n']
    m = case['m']
    if n == 0:
        return 1 if m == 0 else 0
    if m < 0 or m >= n:
        return 0
    prev = [0] * (m + 1)
    prev[0] = 1
    for i in range(2, n + 1):
        cur = [0] * (m + 1)
        for j in range(m + 1):
            val = 0
            if j > 0:
                val += (i - j) * prev[j - 1]
            val += (j + 1) * prev[j]
            cur[j] = val
        prev = cur
    return prev[m]

