from math import isqrt

def solve_case(case):
    limit = case["limit"]
    if limit < 2:
        return 0
    s = [0] * (limit + 1)
    for i in range(1, limit + 1):
        for j in range(2 * i, limit + 1, i):
            s[j] += i
    def prop_sum(x):
        if x <= 1:
            return 0
        total = 1
        r = isqrt(x)
        for i in range(2, r + 1):
            if x % i == 0:
                total += i
                if i != x // i:
                    total += x // i
        return total
    ans = 0
    for a in range(1, limit + 1):
        b = s[a]
        if b == a:
            continue
        if b <= limit:
            if s[b] == a:
                ans += a
        else:
            if prop_sum(b) == a:
                ans += a
    return ans

