import math

def solve_case(case):
    n = case['n']
    decimals = case.get('decimals', 0)
    base = case.get('base', math.pi)
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if n == 0:
        if decimals == 0:
            return '0'
        return '0.' + '0' * decimals
    sign = '-' if n < 0 else ''
    x = abs(n)
    int_digits = []
    if x >= 1.0:
        k = 0
        while base ** (k + 1) <= x:
            k += 1
        for i in range(k, -1, -1):
            pow_val = base ** i
            d = int(math.floor(x / pow_val))
            if d >= base:
                d = int(base) - 1
            if d < 0:
                d = 0
            int_digits.append(d)
            x -= d * pow_val
            if x < 0:
                x = 0.0
    else:
        int_digits.append(0)
    frac_digits = []
    for _ in range(decimals):
        x *= base
        d = int(math.floor(x))
        if d >= base:
            d = int(base) - 1
        if d < 0:
            d = 0
        frac_digits.append(d)
        x -= d
        if x < 0:
            x = 0.0
    int_str = ''.join(chars[d] for d in int_digits)
    if decimals > 0:
        frac_str = ''.join(chars[d] for d in frac_digits)
        return sign + int_str + '.' + frac_str
    return sign + int_str

