from collections import Counter

def solve_case(case):
    s1 = case['s1']
    s2 = case['s2']
    c1 = Counter(ch for ch in s1 if 'a' <= ch <= 'z')
    c2 = Counter(ch for ch in s2 if 'a' <= ch <= 'z')
    parts = []
    for ch in 'abcdefghijklmnopqrstuvwxyz':
        m1 = c1.get(ch, 0)
        m2 = c2.get(ch, 0)
        mx = max(m1, m2)
        if mx <= 1:
            continue
        if m1 == mx and m2 == mx:
            pref = '=:'
        elif m1 == mx:
            pref = '1:'
        else:
            pref = '2:'
        parts.append(pref + ch * mx)
    parts.sort(key=lambda x: (-len(x), x))
    return '/'.join(parts)

